CREATE TABLE IF NOT EXISTS selected_jobs (canonical_job_id TEXT PRIMARY KEY REFERENCES canonical_jobs(id), include_cover_letter INTEGER NOT NULL DEFAULT 1 CHECK(include_cover_letter IN(0,1)), arsenal_version TEXT NOT NULL REFERENCES arsenal_versions(version), selected_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS application_document_revisions (id TEXT PRIMARY KEY, canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), artifact_type TEXT NOT NULL CHECK(artifact_type IN('tailored_resume','cover_letter')), revision INTEGER NOT NULL CHECK(revision>0), parent_revision_id TEXT REFERENCES application_document_revisions(id), ai_draft_id TEXT REFERENCES ai_drafts(id), listing_version_id TEXT NOT NULL REFERENCES listing_versions(id), arsenal_version TEXT NOT NULL REFERENCES arsenal_versions(version), protocol_file_id TEXT NOT NULL, content TEXT NOT NULL, content_hash TEXT NOT NULL CHECK(length(content_hash)=64), mime_type TEXT NOT NULL CHECK(mime_type='application/rtf'), evidence_map_json TEXT NOT NULL, warnings_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(canonical_job_id,artifact_type,revision));
CREATE TABLE IF NOT EXISTS application_document_approvals (document_revision_id TEXT PRIMARY KEY REFERENCES application_document_revisions(id), canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), artifact_type TEXT NOT NULL, revision INTEGER NOT NULL, content_hash TEXT NOT NULL CHECK(length(content_hash)=64), approved_at TEXT NOT NULL);
